with p2 as ( select A.AssetTypeID, A.ID, A.Object, A.ObjectID, cast(null as varchar(50)) as ParentObject, cast(null as int) as ParentObjectID, 1 as [Level], cast(graph.GetXmlSegment(cast(null as xml), @assetTypeID, A.ID, 1) as xml) as Segments, cast(graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join @h H on H.[Level] = 1 and H.ID = A.AssetTypeID left join PredicateIntersect I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID where I.IntersectID is null union all select A.AssetTypeID, A.ID, A.Object, A.ObjectID, p.Object as ParentObject, p.ObjectID as ParentObjectID, p.[Level]+1 as [Level], cast(graph.GetXmlSegment(p.Segments, @assetTypeID, A.ID, p.[Level]+1) as xml) as Segments, cast(p.Segment+'.'+ graph.GetPathSegment(A.ID) as nvarchar(2500)) as Segment from Asset A inner join PredicateIntersect I on I.PredicateType = @predicateType and I.Object = A.Object and I.ObjectID = A.ObjectID inner join p2 as p on p.Object = I.Subject and p.ObjectID = I.SubjectID inner join @h H on H.[Level] = p.[Level]+1 and H.ID = A.AssetTypeID )
update T set T.[Path] = S.Segment, T.[Segments] = S.[Segments] from graph.AssetNode T inner join p2 S on S.AssetTypeID = @assetTypeID and S.ID = T.ID ; end end
